login(role,id){if(role==='introducer'&&!this.s.introducers.some(i=>i.id===id&&i.status!=='Terminated'))throw Error('This is an invitation-only account.');if(!['admin','introducer','applicant'].includes(role))throw Error('Unknown account role.');this.actor={role,id};}
