const baseInvoice=Store.prototype.createInvoice;
Store.prototype.createInvoice=function(id,v){this.owner(id);requireDate(v.date,'Invoice date');if(v.date>this.now().slice(0,10))throw Error('Invoice date cannot be in the future.');if(!['No VAT','VAT charged','Reverse charge','Other — Admin review'].includes(v.treatment))throw Error('Unknown invoice tax treatment.');if(v.allocations.some(a=>!Number.isSafeInteger(a.amount)))throw Error('Invoice allocations must use whole minor units.');const i=this.intro(id),status=i.status;if(!['Active','Suspended','Terminated'].includes(status))throw Error('Existing accrued balances are required for settlement.');try{i.status='Active';const result=baseInvoice.call(this,id,v);this.s.invoices.find(x=>x.id===result).settlementOnly=status!=='Active';return result;}finally{i.status=status;}};
const basePayment=Store.prototype.payment;
Store.prototype.payment=function(id,v){requireDate(v.date,'Payment date');const i=this.s.invoices.find(i=>i.id===id);if(v.date>this.now().slice(0,10)||i&&v.date<i.date)throw Error('Payment date must be on or after invoice date and cannot be future dated.');if(!Number.isSafeInteger(v.amount))throw Error('Payment must use whole minor units.');return basePayment.call(this,id,v);};

